/** Independent reviewed facts, direct zone relations, polynomial identities and CFG paths.
 * Does not import a production generator or use eval/Function. */
import assert from'node:assert/strict';
import type{GeneratedBody}from'../../src/core/generators/definition';import type{Block}from'../../src/core/types';
import facts from'./legacy-2019-autumn-quality-facts.json';
const paragraph=(b:Block)=>{assert.equal(b.type,'paragraph');if(b.type!=='paragraph')throw Error('paragraph');return b.text;};
type Poly=Map<string,number>;
const mono=(s=0,t=0,p=0,c=1):Poly=>new Map([[`${s},${t},${p}`,c]]),add=(a:Poly,b:Poly,sign=1)=>{const r=new Map(a);for(const[k,v]of b)r.set(k,(r.get(k)??0)+v*sign);for(const[k,v]of r)if(v===0)r.delete(k);return r;},mul=(a:Poly,b:Poly)=>{const r=new Map<string,number>();for(const[ka,va]of a)for(const[kb,vb]of b){const k=ka.split(',').map((x,i)=>Number(x)+Number(kb.split(',')[i])).join(',');r.set(k,(r.get(k)??0)+va*vb);}for(const[k,v]of r)if(v===0)r.delete(k);return r;};
/** The grammar is deliberately bounded to sums/differences of S/T/m/n; hostile text fails closed. */
function parseSum(text:string,env:Record<string,Poly>):Poly{assert.match(text,/^[STmn](?:[+-][STmn])*$/);const tokens=text.match(/[+-]?[STmn]/g)!;return tokens.reduce((r,x)=>add(r,env[x.at(-1)!],x[0]==='-'?-1:1),new Map<string,number>());}
export function legacy2019QualityFormulaMeaning(b:Block,v:number){assert.equal(b.type,'formula');if(b.type!=='formula')throw Error('formula');assert.equal(b.format,'latex');const m=b.text.match(/^\\frac\{([^{}]+)\}\{([^{}]+)\}=\\frac\{([^{}]+)\}\{([^{}]+)\}$/);assert(m,'two visible fractions');const s=mono(1),t=mono(0,1),sm=mono(1,0,1),tm=mono(0,1,1),env={S:v&1?add(s,sm,-1):s,T:v&2?add(t,tm,-1):t,m:sm,n:add(sm,tm)};const parts=m.slice(1).map(x=>parseSum(x,env));const residual=add(mul(parts[0],parts[3]),mul(parts[2],parts[1]),-1);const alt=`${m[1].replace(/-/g,'−')}を${m[2].replace(/-/g,'−')}で割った値 ＝ ${m[3].replace(/-/g,'−')}を${m[4].replace(/-/g,'−')}で割った値`;assert.equal(b.alt,alt,'alt reads exactly the visible equation');return{identity:residual.size===0,residual:Object.fromEntries(residual),parts:m.slice(1)};}
function equivalentFormula(source:string,block:Block){assert.equal(block.type,'formula');if(block.type!=='formula')throw Error('formula');const norm=(s:string)=>s.replace(/[\s()]/g,'').replace(/−/g,'-');const m=block.text.match(/^\\frac\{([^{}]+)\}\{([^{}]+)\}=\\frac\{([^{}]+)\}\{([^{}]+)\}$/);assert(m);const [a,b]=source.split('=');assert(a&&b);const parts=[...a.split('/'),...b.split('/')].map(norm);assert.deepEqual(m.slice(1).map(norm),parts,'source numerator and denominator roles');}
export function legacy2019QualityPlacement(text:string):[string,string]{const same=text.match(/^Webサーバとデータベースサーバを(DMZ|外部セグメント|内部セグメント)に設置する。$/);if(same)return[same[1],same[1]];const split=text.match(/^Webサーバを(DMZ|外部セグメント|内部セグメント)に，データベースサーバを(DMZ|外部セグメント|内部セグメント)に設置する。$/);assert(split);return[split[1],split[2]];}
export function legacy2019QualityZoneAssessment(web:string,db:string){const direct=(a:string,b:string)=>!(new Set([a,b]).has('外部セグメント')&&new Set([a,b]).has('内部セグメント'));const publicPossible=direct('外部セグメント',web),backendPossible=direct(web,db),frontendBehindBoundary=web!=='外部セグメント'&&publicPossible,dataBehindDirectDeny=!direct('外部セグメント',db);return{publicPossible,backendPossible,separated:web!==db,frontendBehindBoundary,dataBehindDirectDeny,protected:frontendBehindBoundary&&dataBehindDirectDeny};}
const required:Record<number,string[]>={40:['提供者から事前に電話で直接','完全性','提供者と作成者の同一性','衝突の可能性が数学的にゼロ','作成者の本人確認とは異なる'],41:['DNSは名前解決','SEOは検索結果','ブラウザ内','人の判断','組み合わされる'],42:['外部と内部の直接通信は禁止','両方を内部','境界','具体的なポートやACLは与えられていない','必ず侵害される','という前提は置かない'],43:['ログを収集・統合・相関分析','管理者','集中的に制御','統合製品','連携したりする場合はある'],47:['n−m','発見される割合','一般関係式','分母がゼロ','一般の恒等関係と扱わない','保証される性質ではない'],48:['ドライバはテスト対象を呼ぶ側','スタブはテスト対象から呼ばれる側','スタブを対象の呼出し側','ログ出力やコールバック','禁止ではなく'],49:['命令網羅より強い','判定条件網羅を満たせば命令網羅も満たす','elseのないif','真','偽','語順が異なっても同じ','decision coverage','条件網羅やMC/DCの意味へ置き換えない'],50:['XP','インスペクションは形式的なレビュー','構造化設計','ユースケース','併用できないという禁止ではなく']};
const variant:Record<number,string[][]>={41:[['検索順位','SEOポイズニングである'],['偽のDNS応答','DNSキャッシュポイズニングである'],['別の利用者のブラウザ','クロスサイトスクリプティングである'],['電話','パスワード','ソーシャルエンジニアリングである']],50:[['2人が協働'],['実装に先立ってテスト'],['変更を頻繁に統合','ビルドやテスト'],['外部から見た動作を保ち','内部構造を改善']]};
export function legacy2019QualityExplanationRequirements(n:number,v:number){const r=[...required[n],...(variant[n]?.[v]??[])];if(n===40)r.push(v&1?'作成者本人であることの証明にはならない':'秘密鍵によるディジタル署名にはならず',v&2?'Bだけから元の内容を一意に逆算することはできない':'改ざん箇所を修復することはできない');if(n===42)r.push(v&1?'両方を外部に置く':'両方をDMZに置く',v&2?'両者間の直接通信が禁止される':'Webを外部、DBをDMZ');if(n===43)r.push(v&1?'実行せず命令列や文字列':'仮想環境でファイルを実行',v&2?'HTTP要求を検査しSQLインジェクション':'アプリケーションを識別して通過を制御');if(n===47)r.push(v&1?'埋込エラーの総数はS+m':'Sは埋込エラーの総数',v&2?'元の潜在エラーの総数はT+n−m':'Tは開始前の元の潜在エラー総数');if(n===48)r.push(v&1?'テストデータを引数として渡して結果を収集':'対象から戻る値を受けて表示・印刷',v&2?'DB検索へ決められた検索結果':'ドライバが対象から呼び出される');if(n===49)r.push(v?'未実行の判定結果は増えず':'逆の含意は成立しない');return r;}
export function assertLegacy2019AutumnQuality(source:string,b:GeneratedBody,values:number[]){const n=Number(source.split('-').at(-1)),v=values[0],c=facts.cases.find(c=>c.source===source&&c.input[0]===v);assert(c);assert.equal(values.length,1);assert.equal(b.prompt.length,1);assert.equal(paragraph(b.prompt[0]),c.stem);assert.equal(b.choices.length,4);assert.equal(b.answerParts,undefined);assert.equal(b.partAnswers,undefined);assert.equal(b.contexts,undefined);
 const registry=facts.facts.records as Record<string,{text:string;kind:string;reason:string}>;
 const truth=b.choices.map((blocks,i)=>{assert.equal(blocks.length,1);if(n===47){equivalentFormula(c.choices[i],blocks[0]);return legacy2019QualityFormulaMeaning(blocks[0],v).identity;}const text=paragraph(blocks[0]);assert.equal(text,c.choices[i]);if(n===42){const [web,db]=legacy2019QualityPlacement(text),a=legacy2019QualityZoneAssessment(web,db);return a.publicPossible&&a.backendPossible&&a.separated&&a.protected;}const f=registry[c.factIds[i]];assert(f);assert.equal(f.text,text);if(n===41)return f.kind===c.parameters.scenario;return({40:['trusted-digest-integrity'],43:['integrated-security-log-analysis'],48:['driver-caller'],49:['decision-implies-statement'],50:['xp-practice']}as Record<number,string[]>)[n].includes(f.kind);});assert.equal(truth.filter(Boolean).length,1);assert.equal(b.correctIndex,truth.indexOf(true));for(const s of legacy2019QualityExplanationRequirements(n,v))assert(b.explanation.includes(s),`${source}/${v} explanation missing: ${s}`);assert(!/生成条件|転載|編集方針|原[アイウエ]の|左から順|選択肢は順/.test(b.explanation));return truth;}
/** Executable two-if counterexample plus all reachable forward CFGs/suites. */
export function legacy2019QualityCoverage(){let graphs=0,suites=0,weakNotStrong=0,strongNotWeak=0,repetitions=0;const examples:unknown[]=[];
 // Four executable nodes, two decisions0/2 and statements1/3; exit4.
 for(let t0=1;t0<=4;t0++)for(let f0=1;f0<=4;f0++)for(let e1=2;e1<=4;e1++)for(let t2=3;t2<=4;t2++)for(let f2=3;f2<=4;f2++){
  const edges=[[t0,f0],[e1],[t2,f2],[4]],reachable=new Set<number>([0]),front=[0];while(front.length){const x=front.pop()!;for(const next of edges[x]??[])if(!reachable.has(next)){reachable.add(next);front.push(next);}}if(reachable.size!==5)continue;graphs++;
  const paths:{nodes:Set<number>;branches:Set<string>}[]=[],pathKeys=new Set<string>();for(let a=0;a<2;a++)for(let b=0;b<2;b++){const nodes=new Set<number>(),branches=new Set<string>();let x=0;while(x!==4){nodes.add(x);if(x===0||x===2){const take=x===0?a:b;branches.add(`${x}:${take}`);x=edges[x][take];}else x=edges[x][0];}const key=JSON.stringify([[...nodes].sort(),[...branches].sort()]);if(!pathKeys.has(key)){pathKeys.add(key);paths.push({nodes,branches});}}
  for(let mask=0;mask<2**paths.length;mask++){const chosen=paths.filter((_,i)=>mask>>i&1),nodes=new Set(chosen.flatMap(p=>[...p.nodes])),branches=new Set(chosen.flatMap(p=>[...p.branches])),statement=[0,1,2,3].every(x=>nodes.has(x)),decision=['0:0','0:1','2:0','2:1'].every(x=>branches.has(x));if(statement&&!decision){weakNotStrong++;if(examples.length<3)examples.push({edges,mask});}if(decision&&!statement)strongNotWeak++;for(let k=1;k<=8;k++){assert.deepEqual(new Set(Array.from({length:k},()=>chosen.flatMap(p=>[...p.nodes])).flat()),nodes);assert.deepEqual(new Set(Array.from({length:k},()=>chosen.flatMap(p=>[...p.branches])).flat()),branches);repetitions++;}suites++;}
 }return{graphs,suites,weakNotStrong,strongNotWeak,repetitions,examples};}
